//! Dungeon Pickup Database
//!
//! GENERATED — do not hand-edit. Regenerate with
//!   `er-save-editor knowledge gen-dungeon-pickups`
//! (`src/knowledge/gen_dungeon_pickups.rs`). `tests/dungeon_pickups_generated.rs`
//! asserts this file equals the generator's output for the committed source, so a
//! hand-edit or a stale table fails the test.
//!
//! Source: the primary `ItemLotParam_map.param.xml` (regulation 1.16.1, evidence
//! corpus `game-extracts`, verified against knowledge/manifests/game-extracts.sha256).
//!
//! Set: every row whose `getItemFlagId` is an 8-digit legacy-dungeon flag
//! (10,000,000..44,000,000) with localId >= 7000 AND that grants an item
//! (lotItemId01 != 0) -> 2031 pickups. Empty lots (a flag but no item) are
//! excluded. Per row: item_lot_id = row id, event_flag = getItemFlagId
//! (authoritative — several lot rows can share one flag, e.g. an armor set's
//! pieces), item_id = lotItemId01, quantity = lotItemNum01 (default 1), name from
//! paramdexName, area/section derived from the flag, category from a documented
//! classifier over the name + lotItemCategory.

use crate::db::pickup_data::PickupCategory;

/// A dungeon pickup entry
#[derive(Debug, Clone)]
pub struct DungeonPickup {
pub item_lot_id: u32,
pub event_flag: u32,
pub item_id: u32,
pub name: &'static str,
pub quantity: u32,
pub category: PickupCategory,
pub region: &'static str,
pub dungeon_area: u32,
pub section: u32,
}

/// Dungeon area names for display
pub fn get_dungeon_area_name(area: u32) -> &'static str {
    match area {
        10 => "Stormveil Castle",
        11 => "Leyndell",
        12 => "Underground",
        13 => "Crumbling Farum Azula",
        14 => "Academy of Raya Lucaria",
        15 => "Haligtree",
        16 => "Volcano Manor",
        18 => "Roundtable Hold",
        20 => "Stranded Graveyard",
        21 => "Haligtree (Elphael)",
        22 => "Castle Sol",
        28 => "DLC Dungeon",
        30 => "Catacombs",
        31 => "Caves",
        32 => "Tunnels",
        34 => "Divine Towers",
        35 => "Mohgwyn Palace",
        39 => "Elden Throne",
        40 => "Hero's Graves",
        41 => "Minor Dungeons",
        42 => "Crystal Caves",
        43 => "Evergaols",
        59 => "Unknown 59",
        99 => "Special",
        _ => "Unknown",
    }
}

